import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"红蓝对抗","description":"","frontmatter":{"title":"红蓝对抗","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/red-blue-team.md","filePath":"cs/red-blue-team.md","lastUpdated":1789023840000}'),c={name:"cs/red-blue-team.md"};function m(u,a,E,T,_,b){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="红蓝对抗" tabindex="-1">红蓝对抗 <a class="header-anchor" href="#红蓝对抗" aria-label="Permalink to &quot;红蓝对抗&quot;">​</a></h1><div class="epigraph"><p>红队在授权下模拟对手，蓝队检测与响应，紫队让两边共用同一套遥测与教训。对抗的产品是检测覆盖与响应时间，不是一份「打穿了」的战报。</p><footer>—— 据 NIST 对红队的讨论；MITRE 对 ATT&amp;CK 评估的实践；对照 Anderson 对激励</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/pentest-methodology">渗透测试</a>有明确窗口。缺口是<strong>持续对抗与紫队闭环</strong>。本课讲组织角色，不写红队利用配方。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次渗透测试后控制回潮。红蓝持续：假设已被突破（assume breach）测检测。缺口是安全的度量：MTTD/MTTR，而不是红队积分。</p><h3 id="激励" tabindex="-1">激励 <a class="header-anchor" href="#激励" aria-label="Permalink to &quot;激励&quot;">​</a></h3><p>红队若只以打穿为荣，会隐藏可修复的检测改进。紫队改激励。</p><p><span class="marginnote">授权与范围仍然必要。禁止未授权。下一单元系统与硬件从 SELinux 起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>assume breach 场景、检测工程、复盘进 ATT&amp;CK 覆盖。网络防御课序封口。</p>',12)),(e(),n(h,null,{default:r(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RED%5B%22%E6%8E%88%E6%9D%83%E6%A8%A1%E6%8B%9F%22%5D%20--%3E%20BLUE%5B%22%E6%A3%80%E6%B5%8B%E5%93%8D%E5%BA%94%22%5D%0A%20%20BLUE%20--%3E%20PURPLE%5B%22%E5%85%B1%E5%90%8C%E9%81%A5%E6%B5%8B%E4%B8%8E%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20PURPLE%20--%3E%20MET%5B%22MTTD%20MTTR%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>组织学习循环。下一单元从强制访问控制与提权路径谈系统层。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写利用。下一单元第一课 SELinux 类型强制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>渗透测试有窗口；红蓝是持续授权对抗。</li><li>产品是检测与响应，不是战报炫耀。</li><li>紫队改激励，让洞变成覆盖。</li><li>下一单元：SELinux。</li><li>出处：NIST 红队讨论；MITRE ATT&amp;CK；Anderson。</li></ul>',8))])}const B=l(c,[["render",m]]);export{A as __pageData,B as default};
